def solve(intervals):
    if not intervals:
        return []
    # sort by start
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0][:]]
    for start, end in intervals[1:]:
        last = merged[-1]
        if start <= last[1]:  # overlap or touch (since last[1] >= start)
            # merge
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

