def solve(tokens):
    """Evaluate an RPN expression given as list of string tokens.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    Returns the integer result.
    """
    stack = []
    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                # truncates toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

