def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Tokens are strings representing integers or the operators +, -, *, /.
    Division should truncate toward zero, matching Python's int()/trunc behavior.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

