def solve(tokens):
    """Evaluate Reverse Polish Notation expression for batch 2.
    Supports the operators +, -, *, /. Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # truncates toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

